'use strict';
// Rich pictures are assembled locally from authored story actions, characters and scenery.
let worldState=null,worldProgress={};try{const p=JSON.parse(localStorage.getItem('spotmatch-world-v1')||'{}');if(p&&typeof p==='object'&&!Array.isArray(p))worldProgress=p;}catch{}
const worldModes=['sequence','puzzle','pack','compare','director'];
const worldModeNames={sequence:'Put the story together',puzzle:'Make the whole picture',pack:'Pack for our adventure',compare:'Look at the whole scene',director:'Be the story director'};
function worldHelpArt(kind){const scene=worldScene(kind===1?2:0,kind===0?2:1,kind===2?5:0,0);return `<svg viewBox="0 0 260 180" aria-hidden="true"><rect x="2" y="2" width="256" height="176" rx="24" fill="${['#e4f1ff','#fff0ca','#fce4d9'][kind]}"/>${kind===0?`<svg x="15" y="21" width="230" height="138" viewBox="0 0 800 480">${svgBody(scene)}</svg><path d="M30 155h197" stroke="#549ac4" stroke-width="6" stroke-linecap="round"/>`:kind===1?`<svg x="8" y="17" width="62" height="70" viewBox="0 0 120 120">${svgBody(pictureIcon('cup'))}</svg><svg x="51" y="45" width="62" height="70" viewBox="0 0 120 120">${svgBody(pictureIcon('ball'))}</svg><svg x="8" y="85" width="62" height="70" viewBox="0 0 120 120">${svgBody(pictureIcon('book'))}</svg><path d="M112 90h30m-10-12 12 12-12 12" stroke="#b37a40" stroke-width="5" fill="none"/><svg x="157" y="36" width="80" height="100" viewBox="0 0 120 120">${svgBody(pictureIcon('cup'))}</svg>`:`<svg x="10" y="10" width="115" height="160" viewBox="0 0 240 300">${svgBody(worldCharacterArt(4))}</svg><svg x="135" y="58" width="90" height="115" viewBox="0 0 240 300">${svgBody(worldCharacterArt(5))}</svg><path d="M86 150q44 24 84 0" stroke="#bc7d61" stroke-width="5" fill="none"/>`}</svg>`;}
function worldSave(){try{localStorage.setItem('spotmatch-world-v1',JSON.stringify(worldProgress));}catch{}}
function worldStart(index,help=null){const visit=nextPictureVisit('world',index);worldState={index,character:visit%12,variant:Math.floor(visit/12)%8,mode:worldModes[index%worldModes.length],slots:[null,null,null,null],selected:null,packed:[],step:0,finished:false,help,message:'',hint:help===0,choice:null};if(help!==null){worldState.mode='puzzle';if(help===1)worldState.slots=[0,1,null,null];}worldRender();window.scrollTo(0,0);}
function worldExit(){worldState=null;if(skillContext)skillCourse(skillContext.courseId);else skillHome();}
function worldPart(i,klass='',attributes=''){const s=worldState;return `<button class="world-picture ${klass}" ${attributes}>${worldScene(s.index,i,s.character,s.variant)}<span>${senEscape(worldStories[s.index].steps[i])}</span></button>`;}
function worldPuzzlePiece(piece){const s=worldState,x=piece%2*400,y=Math.floor(piece/2)*240;return `<svg viewBox="${x} ${y} 400 240" aria-hidden="true">${svgBody(worldScene(s.index,3,s.character,s.variant))}</svg>`;}
function worldSay(message){worldState.message=message;worldRender();}
function worldCheck(){const s=worldState;if(s.finished)return;let ok=false;if(s.mode==='sequence'||s.mode==='puzzle'){if(s.slots.some(x=>x===null))return;ok=s.slots.every((v,i)=>v===i);if(!ok){s.message='One piece needs another look. You can move it or ask for help.';worldRender();return;}}else if(s.mode==='pack')ok=worldStories[s.index].objects.slice(0,3).every(v=>s.packed.includes(v));else if(s.mode==='compare')ok=s.choice===s.step;if(ok){s.finished=true;s.message='Great! You made it happen.';worldRender();setTimeout(()=>{if(worldState===s&&s.finished&&!s.paused&&app.querySelector('.world-play'))worldFinish();},1100);}}
function worldPlace(piece,slot){const s=worldState;if(s.finished)return;const from=s.slots.indexOf(piece),old=s.slots[slot];if(from>=0)s.slots[from]=old;s.slots[slot]=piece;s.selected=null;s.message='';worldRender();worldCheck();}
function worldPack(item){const s=worldState;if(s.finished)return;const needed=worldStories[s.index].objects.slice(0,3);if(!needed.includes(item)){worldSay('That can stay here. Look at our picture list.');return;}if(!s.packed.includes(item))s.packed.push(item);s.message='In the bag!';worldRender();worldCheck();}
function worldCompare(i){const s=worldState;if(s.finished)return;s.choice=i;if(i!==s.step){worldSay('Look at what is happening, as well as who is there. Try another scene.');return;}worldCheck();}
function worldRender(){const s=worldState;if(!s)return;const d=worldStories[s.index],mode=s.mode;let body='',instruction='';
 if(mode==='sequence'){instruction='Give each picture a place. What happened first, next, and last?';body=`<div class="world-story-slots">${s.slots.map((piece,i)=>`<button class="world-story-slot ${piece===null?'empty':''}" data-world-slot="${i}" aria-label="Story position ${i+1}${piece===null?', empty':': '+senEscape(d.steps[piece])}">${piece===null?`<span class="world-slot-number">${i+1}</span><small>A picture goes here</small>`:worldScene(s.index,piece,s.character,s.variant)}</button>`).join('')}</div><div class="world-story-palette" aria-label="Story pictures">${[2,0,3,1].filter(i=>!s.slots.includes(i)).map(i=>worldPart(i,s.selected===i?'selected':'',`data-world-piece="${i}" aria-label="${senEscape(d.steps[i])}"`)).join('')}</div>`;}
 if(mode==='puzzle'){instruction=s.help===1?'Two pieces are already in place. Add the other two.':'Build the big picture. Fit the four picture pieces into their spaces.';body=`<div class="world-puzzle-layout"><div class="world-puzzle-model"><span>Our picture</span>${worldScene(s.index,3,s.character,s.variant)}</div><div class="world-puzzle-board" aria-label="Your picture puzzle">${s.slots.map((piece,i)=>`<button class="world-puzzle-slot ${piece===null?'empty':''}" data-world-slot="${i}" aria-label="Puzzle space ${i+1}${piece===null?', empty':', contains piece '+(piece+1)}">${piece===null?`<span>${i+1}</span>`:worldPuzzlePiece(piece)}</button>`).join('')}</div></div><div class="world-puzzle-palette">${[3,1,0,2].filter(i=>!s.slots.includes(i)).map(i=>`<button class="world-puzzle-piece ${s.selected===i?'selected':''}" data-world-piece="${i}" aria-label="Picture piece ${i+1}">${worldPuzzlePiece(i)}</button>`).join('')}</div>`;}
 if(mode==='pack'){const items=d.objects.slice(0,3),extras=['ball','hat','key'].filter(v=>!items.includes(v)).slice(0,2);instruction='Our adventure needs these things. Put them in the bag; the picture list stays here.';body=`<div class="world-packing-scene">${worldScene(s.index,0,s.character,s.variant)}<div class="world-packing-list" aria-label="Things we need">${items.map(id=>`<span class="${s.packed.includes(id)?'packed':''}">${worldObjectArt(id)}<span>${s.packed.includes(id)?'✓ ':''}${senEscape((worldObjectNames[id]||nameOf(id)))}</span></span>`).join('')}</div></div><div class="world-bag" id="worldBag" role="group" aria-label="Our adventure bag"><div class="world-bag-icon">${pictureIcon('basket')}</div><div><b>Our adventure bag</b><div class="world-bag-items">${s.packed.length?s.packed.map(id=>`<span data-packed-item="${id}">${worldObjectArt(id)}<small>${senEscape((worldObjectNames[id]||nameOf(id)))}</small></span>`).join(''):'<span>Drop things here, or tap a picture below.</span>'}</div></div></div><div class="world-object-palette">${[...items,...extras].filter(id=>!s.packed.includes(id)).map(id=>`<button data-world-object="${id}" aria-label="Pack ${senEscape((worldObjectNames[id]||nameOf(id)))}">${worldObjectArt(id)}<span>${senEscape((worldObjectNames[id]||nameOf(id)))}</span></button>`).join('')}</div>`;}
 if(mode==='compare'){s.step=2;instruction='Our big picture tells a little story. Which scene below shows the same moment?';body=`<div class="world-compare-model">${worldScene(s.index,s.step,s.character,s.variant)}</div><div class="world-compare-options">${[3,1,2].map(i=>worldPart(i,s.choice===i?'selected':'',`data-world-compare="${i}" aria-label="${senEscape(d.steps[i])}"`)).join('')}</div>`;}
 if(mode==='director'){instruction='Choose your cast and setting. Move through the pictures and tell the story your way.';body=`<div class="world-director-stage" id="worldStage">${worldScene(s.index,s.step,s.character,s.variant)}</div><p class="world-story-caption">${senEscape(d.steps[s.step])}</p><div class="world-director-controls"><button class="secondary" id="worldStoryPrev" ${s.step===0?'disabled':''}>← Before</button><button class="primary" id="worldStoryNext" ${s.step===3?'disabled':''}>What happens next? →</button></div><div class="world-cast" aria-label="Choose your story character">${worldCharacters.map((c,i)=>`<button data-world-character="${i}" aria-label="${senEscape(c.name)}" aria-pressed="${s.character===i}">${worldCharacterArt(i)}</button>`).join('')}</div><div class="world-setting-controls"><button class="secondary" id="worldChangeSetting">Change the scenery ✨</button><button class="primary" id="worldFinishStory">Save our story →</button></div>`;}
 app.innerHTML=`<div class="play-top"><button class="back" id="worldBack">← Back to the course</button><span class="together-note">♧ Play together</span></div><section class="game-wrap world-play"><div class="world-play-heading"><div><span class="eyebrow">${worldModeNames[mode]}</span><h1>${senEscape(d.title)}</h1><p class="play-invitation">${instruction}</p></div><span class="world-character-badge">${worldCharacterArt(s.character)}</span></div>${s.help===2?'<p class="world-together-banner">Take turns together. A grown-up can show one piece; the child chooses the next.</p>':''}${s.hint?`<aside class="world-example"><b>A picture to keep beside you</b>${worldScene(s.index,3,s.character,s.variant)}<p>Look at one part, then find its piece. Keep this help as long as useful.</p></aside>`:''}<div class="world-game-board">${body}</div><p class="world-feedback ${s.finished?'success':''}" role="status" aria-live="polite">${senEscape(s.message||'Drag or tap. There is no hurry.')}</p><div class="world-footer"><button class="secondary" id="worldHelp">${s.hint?'Hide the extra model':'Show me an example'}</button><button class="secondary" id="worldReset">Start this picture again</button><button class="back" id="worldPause">${s.paused?'Continue at my pace':'Pause automatic progress'}</button><button class="back" id="worldStop">Finish for now</button>${s.finished&&s.paused?'<button class="primary" id="worldContinue">Continue →</button>':''}</div><details class="quiet-notes"><summary>For grown-ups · our goal</summary><p>${mode==='sequence'?'Connect four visible events into a meaningful sequence. Model the story first.':mode==='puzzle'?'Compare parts with a visible whole. Fit pictures using size, position and meaningful details.':mode==='pack'?'Use a visible plan to collect purposeful items. This is supported planning and vocabulary practice.':mode==='compare'?'Compare whole scenes, including the action, rather than choosing by one detail.':'Explore shared storytelling and communication. Follow the child’s contribution; there is no wrong narration.'}</p><p>Use speech, signs, pointing, or AAC. Repeat, simplify, or stop. These are educational play activities, not a validated intervention or an assessment of reading readiness.</p><p><b>Try away from the screen:</b> ${mode==='pack'?'Pack a few familiar real objects using a short picture list.':'Act out or retell one familiar event together, using real objects or photographs.'}</p></details></section>`;skillNav();const bind=(id,fn)=>{const b=document.getElementById(id);if(b)b.onclick=fn;};bind('worldBack',worldExit);bind('worldStop',worldFinish);bind('worldHelp',()=>{s.hint=!s.hint;worldRender();});bind('worldReset',()=>{s.slots=s.help===1?[0,1,null,null]:[null,null,null,null];s.packed=[];s.finished=false;s.choice=null;s.selected=null;s.message='A fresh picture. Try it together.';worldRender();});bind('worldPause',()=>{s.paused=!s.paused;if(s.finished&&!s.paused)worldFinish();else worldRender();});bind('worldContinue',worldFinish);bind('worldStoryPrev',()=>{s.step--;worldRender();});bind('worldStoryNext',()=>{s.step++;worldRender();});bind('worldChangeSetting',()=>{s.variant=(s.variant+1)%8;worldRender();});bind('worldFinishStory',worldFinish);
 app.querySelectorAll('[data-world-piece]').forEach(b=>b.onclick=()=>{s.selected=+b.dataset.worldPiece;s.message='Choose a space, or drag this picture into one.';worldRender();});app.querySelectorAll('[data-world-slot]').forEach(b=>b.onclick=()=>{const slot=+b.dataset.worldSlot;if(s.selected!==null)worldPlace(s.selected,slot);else if(s.slots[slot]!==null){s.selected=s.slots[slot];s.message='Choose another space to move this picture.';worldRender();}});app.querySelectorAll('[data-world-object]').forEach(b=>b.onclick=()=>worldPack(b.dataset.worldObject));app.querySelectorAll('[data-world-compare]').forEach(b=>b.onclick=()=>worldCompare(+b.dataset.worldCompare));app.querySelectorAll('[data-world-character]').forEach(b=>b.onclick=()=>{s.character=+b.dataset.worldCharacter;worldRender();});
}
function worldFinish(){const s=worldState;if(!s)return;worldProgress[s.index]={explored:true};worldSave();const d=worldStories[s.index];app.innerHTML=`<section class="game-wrap world-completion"><span class="eyebrow">A STORY TO SHARE</span><h1>${senEscape(d.title)}</h1><div class="world-finished-strip">${d.steps.map((caption,i)=>`<figure>${worldScene(s.index,i,s.character,s.variant)}<figcaption>${senEscape(caption)}</figcaption></figure>`).join('')}</div><p>Point, sign, speak, or use AAC to share one part of the story. A grown-up can tell it with you.</p><div class="calm-controls"><button class="secondary" id="worldAgain">Play this adventure again</button><button class="primary" id="worldReturn">Back to the course</button><button class="secondary" id="worldDownload">Save our picture story ↓</button></div></section>`;skillNav();document.getElementById('worldAgain').onclick=()=>worldStart(s.index,s.help);document.getElementById('worldReturn').onclick=worldExit;document.getElementById('worldDownload').onclick=()=>worldDownload(s.index,s.character,s.variant);window.scrollTo(0,0);}
function worldDownload(index,character,variant){const d=worldStories[index],svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 1100"><rect width="1600" height="1100" fill="#fffdf5"/>${d.steps.map((step,i)=>`<svg x="${i%2*800}" y="${Math.floor(i/2)*550}" width="800" height="480" viewBox="0 0 800 480">${svgBody(worldScene(index,i,character,variant))}</svg><text x="${i%2*800+24}" y="${Math.floor(i/2)*550+515}" font-family="sans-serif" font-size="21" fill="#254d43">${senEscape(step)}</text>`).join('')}</svg>`,url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='picture-story-'+d.id+'.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function worldGallery(index=0,character=0,variant=0){skillContext=null;skillFreePlay=false;app.innerHTML=`<section class="world-gallery"><button class="back" id="worldGalleryBack">← All skills</button><span class="eyebrow">OUR PICTURE & STORY LIBRARY</span><h1>Little worlds. Lots to talk about.</h1><p>24 illustrated stories, 12 characters, and 8 scenery variations: 2,304 picture-story combinations, made here in the app. Each has four pictures that show what happens.</p><div class="world-gallery-filters"><label>Our story<select id="worldPickStory">${worldStories.map((s,i)=>`<option value="${i}" ${i===index?'selected':''}>${s.title}</option>`).join('')}</select></label><label>Our character<select id="worldPickCharacter">${worldCharacters.map((c,i)=>`<option value="${i}" ${i===character?'selected':''}>${c.name}</option>`).join('')}</select></label><button class="secondary" id="worldGalleryScene">Another setting ✨</button></div><div class="world-gallery-feature">${worldStories[index].steps.map((text,i)=>`<figure>${worldScene(index,i,character,variant)}<figcaption>${senEscape(text)}</figcaption></figure>`).join('')}</div><div class="calm-controls"><button class="primary" id="worldGalleryPlay">Play this picture adventure →</button><button class="secondary" id="worldGalleryDownload">Save these four pictures ↓</button></div><h2>Explore a different story</h2><div class="world-gallery-grid">${worldStories.map((s,i)=>`<button data-world-book="${i}">${worldScene(i,2,(i+character)%12,variant)}<b>${senEscape(s.title)}</b><small>Four pictures · ${worldModeNames[worldModes[i%worldModes.length]]}</small></button>`).join('')}</div></section>`;skillNav();document.getElementById('worldGalleryBack').onclick=skillHome;document.getElementById('worldPickStory').onchange=e=>worldGallery(+e.target.value,character,variant);document.getElementById('worldPickCharacter').onchange=e=>worldGallery(index,+e.target.value,variant);document.getElementById('worldGalleryScene').onclick=()=>worldGallery(index,character,(variant+1)%8);document.getElementById('worldGalleryDownload').onclick=()=>worldDownload(index,character,variant);document.getElementById('worldGalleryPlay').onclick=()=>{skillLaunch('picture-adventures',index);worldState.character=character;worldState.variant=variant;worldRender();};app.querySelectorAll('[data-world-book]').forEach(b=>b.onclick=()=>{worldGallery(+b.dataset.worldBook,character,variant);window.scrollTo(0,0);});}
TouchPlay.register(bind=>{if(!app.querySelector('.world-play')||!worldState||worldState.finished)return;const s=worldState,slots=()=>[...app.querySelectorAll('[data-world-slot]')];app.querySelectorAll('[data-world-piece]').forEach(b=>bind(b,{targets:slots,drop:target=>worldPlace(+b.dataset.worldPiece,+target.dataset.worldSlot)}));slots().forEach(b=>{const i=+b.dataset.worldSlot;if(s.slots[i]!==null)bind(b,{targets:()=>slots().filter(x=>x!==b),drop:target=>worldPlace(s.slots[i],+target.dataset.worldSlot)});});app.querySelectorAll('[data-world-object]').forEach(b=>bind(b,{targets:()=>[document.getElementById('worldBag')],drop:()=>worldPack(b.dataset.worldObject)}));app.querySelectorAll('[data-world-character]').forEach(b=>bind(b,{targets:()=>[document.getElementById('worldStage')],drop:()=>{s.character=+b.dataset.worldCharacter;worldRender();}}));});

// Activities opened from the optional catalogue start their own context.
const worldOriginalParents=prParents;prParents=function(...args){worldOriginalParents(...args);app.querySelectorAll('[data-pr-legacy],[data-pr-support],[data-pr-calm],[data-pr-focus]').forEach(button=>{const launch=button.onclick;button.onclick=()=>{skillContext=null;launch?.();};});};
